/**
 * Real film grain: fractal noise generated by the browser and blended
 * over the page, rather than a repeating dot bitmap. One SVG, no image
 * request, and it never tiles visibly.
 */
export default function FilmGrain() {
  return (
    <svg className="grain" aria-hidden="true" focusable="false">
      <filter id="filmGrain">
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.72"
          numOctaves="4"
          stitchTiles="stitch"
          result="noise"
        />
        {/* Drain the colour so the grain reads as silver, not rainbow static. */}
        <feColorMatrix in="noise" type="saturate" values="0" />
      </filter>
      <rect width="100%" height="100%" filter="url(#filmGrain)" />
    </svg>
  )
}
